-- ============================================================================
-- Seed 5 AI-verified Vietnamese hashtags for 1103 valid images
-- Run once in Supabase Dashboard > SQL Editor
-- ============================================================================

alter table public.images add column if not exists hashtags text[] not null default '{}'::text[];
create index if not exists idx_images_hashtags_gin on public.images using gin (hashtags);

update public.images as i
set hashtags = v.tags
from (values
